<?php
require_once __DIR__.'/../../includes/staff/operations.php';require_permission('task.view_own');verify_csrf();$pdo=staff_db();$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['task_id'];$status=$_POST['status'];$pdo->prepare("UPDATE tasks SET status=?,completed_at=IF(?='completed',NOW(),NULL) WHERE id=? AND assigned_to=?")->execute([$status,$status,$id,$staff['id']]);$q=$pdo->prepare('SELECT project_id,title FROM tasks WHERE id=?');$q->execute([$id]);$t=$q->fetch();if($t&&$t['project_id'])project_activity($pdo,(int)$t['project_id'],'task_status','Task updated',$t['title'].' → '.str_replace('_',' ',$status));flash('success','Task updated.');staff_redirect('staff/pages/tasks.php');}
$s=$pdo->prepare("SELECT t.*,p.project_code,p.name project_name,c.name customer_name FROM tasks t LEFT JOIN projects p ON p.id=t.project_id LEFT JOIN customers c ON c.id=t.customer_id WHERE t.assigned_to=? ORDER BY FIELD(t.status,'in_progress','todo','waiting','completed','cancelled'),t.due_date IS NULL,t.due_date");$s->execute([$staff['id']]);$rows=$s->fetchAll();$pageTitle='My Tasks';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Work</p><h1>My tasks</h1><p class="muted">Tasks assigned to you, including linked customer projects.</p></div><a class="btn" href="<?= h(ideare_root_url('staff/pages/calendar.php')) ?>">Calendar</a></div><div class="task-grid"><?php foreach($rows as $r):?><article class="staff-panel task-card"><div class="rowtop"><span class="pill <?= h($r['priority']) ?>"><?= h($r['priority']) ?></span><span class="pill <?= h($r['status']) ?>"><?= h(str_replace('_',' ',$r['status'])) ?></span></div><h2><?= h($r['title']) ?></h2><?php if($r['project_id']):?><p class="tiny"><a href="<?= h(ideare_root_url('staff/pages/project-view.php?id='.$r['project_id'])) ?>"><?= h($r['project_code'].' · '.$r['project_name']) ?></a><?php if($r['customer_name']):?> · <?= h($r['customer_name']) ?><?php endif;?></p><?php endif;?><p><?= h($r['description']?:'') ?></p><small><?= $r['due_date']?h(date('j M Y, g:i A',strtotime($r['due_date']))):'No due date' ?></small><form method="post" class="inline-form" style="margin-top:14px"><?= csrf_field() ?><input type="hidden" name="task_id" value="<?= $r['id'] ?>"><select name="status"><?php foreach(['todo'=>'To do','in_progress'=>'In progress','waiting'=>'Waiting','completed'=>'Completed'] as $k=>$v):?><option value="<?= $k ?>" <?= $r['status']===$k?'selected':'' ?>><?= h($v) ?></option><?php endforeach;?></select><button class="btn">Update</button></form></article><?php endforeach;?><?php if(!$rows):?><section class="staff-panel empty-state">No tasks assigned.</section><?php endif;?></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
